SELECT DATE_FORMAT(o.created_at, '%Y-%m-%d') AS date, SUM(oi.price * oi.quantity) AS sales, COUNT(DISTINCT o.id) AS orderCount FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.created_at >= #{startDate} AND o.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID' GROUP BY DATE_FORMAT(o.created_at, '%Y-%m-%d') ORDER BY date ASC

SELECT DATE_FORMAT(o.created_at, '%Y-%m') AS date, SUM(oi.price * oi.quantity) AS sales, COUNT(DISTINCT o.id) AS orderCount FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.created_at >= #{startDate} AND o.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID' GROUP BY DATE_FORMAT(o.created_at, '%Y-%m') ORDER BY date ASC

SELECT IFNULL(SUM(oi.price * oi.quantity), 0) FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.created_at >= #{startDate} AND o.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID'

SELECT COUNT(DISTINCT o.id) FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.created_at >= #{startDate} AND o.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID'
